#!/usr/bin/env python3
"""
deploy-employee-fixes.py  —  员工管理 4 Bug 修复自部署脚本
直接在服务器上运行，无需额外上传文件。
运行: python3 deploy-employee-fixes.py
"""
import base64, os, subprocess, sys

PAYLOAD = """\
"""

script = base64.b64decode(PAYLOAD).decode()
tmp = '/tmp/fix-employee-mgmt-v2.py'
with open(tmp, 'w') as f:
    f.write(script)
os.chmod(tmp, 0o755)
print('已写入临时文件:', tmp)
print()
subprocess.run([sys.executable, tmp], check=False)
